//! PROTOTYPE guest: Rust generated by the typed back end (gen/rs-typed), behind exactly the ABI
//! hostgo/host/shared.go speaks (in_buf, <bidder>_mr / _mb, out_ptr; the same frames).
use std::cell::RefCell;

#[cfg(feature = "openx")]
#[path = "../../gen/rs-typed/openx.rs"]
pub mod openx;
#[cfg(feature = "pubmatic")]
#[path = "../../gen/rs-typed/pubmatic.rs"]
pub mod pubmatic;

thread_local! {
    static IN: RefCell<Vec<u8>> = RefCell::new(Vec::new());
    static OUT: RefCell<Vec<u8>> = RefCell::new(Vec::new());
}

#[no_mangle]
pub extern "C" fn in_buf(n: u32) -> *mut u8 {
    IN.with(|b| {
        let mut b = b.borrow_mut();
        b.resize(n as usize, 0);
        b.as_mut_ptr()
    })
}
#[no_mangle]
pub extern "C" fn out_ptr() -> *const u8 {
    OUT.with(|b| b.borrow().as_ptr())
}
fn run(f: impl FnOnce(&[u8], &mut Vec<u8>)) -> u32 {
    IN.with(|i| {
        OUT.with(|o| {
            let i = i.borrow();
            let mut o = o.borrow_mut();
            o.clear();
            f(&i, &mut o);
            o.len() as u32
        })
    })
}
macro_rules! exports {
    ($feat:literal, $m:ident, $mr:ident, $mb:ident) => {
        #[cfg(feature = $feat)]
        #[no_mangle]
        pub extern "C" fn $mr(len: u32) -> u32 {
            run(|i, o| {
                let inp = prebid_core_rt2::utf8_input(&i[..len as usize]);
                $m::make_requests(&inp, o)
            })
        }
        #[cfg(feature = $feat)]
        #[no_mangle]
        pub extern "C" fn $mb(req_len: u32, resp_len: u32) -> u32 {
            let (q, s) = (req_len as usize, resp_len as usize);
            run(|i, o| {
                let (rq, rs) = (prebid_core_rt2::utf8_input(&i[..q]), prebid_core_rt2::utf8_input(&i[q..q + s]));
                $m::make_bids(&rq, &rs, o)
            })
        }
    };
}
exports!("openx", openx, openx_mr, openx_mb);
exports!("pubmatic", pubmatic, pubmatic_mr, pubmatic_mb);

/// Research hook (bench): the scan floor.
#[no_mangle]
pub extern "C" fn scan(len: u32) -> u32 {
    IN.with(|i| prebid_core_rt2::scan(&i.borrow()[..len as usize]) as u32)
}
